     1	/**
     2	 * Computes the premium for a quote: the policy base premium from the MHPCO price list,
     3	 * the policy-wide modifiers, and finally the processing fee.
     4	 */
     5	public class PremiumCalculator {
     6	
     7	    private static final int PROCESSING_FEE = 5;
     8	    private static final double INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.10;
     9	
    10	    private final PolicyBasePremium policyBasePremiumRule = new PolicyBasePremium();
    11	
    12	    public int premiumFor(QuoteStep quoteStep) {
    13	        double policyBasePremium = policyBasePremiumRule.forItems(quoteStep.items());
    14	        double withPolicyModifiers = policyBasePremium + initialAssessmentSurcharge(policyBasePremium);
    15	        return roundInOfficesFavour(withPolicyModifiers + PROCESSING_FEE);
    16	    }
    17	
    18	    private double initialAssessmentSurcharge(double policyBasePremium) {
    19	        return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    20	    }
    21	
    22	    private int roundInOfficesFavour(double premium) {
    23	        return (int) Math.ceil(premium);
    24	    }
    25	}
