import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium the office charges for a single insured item.
 *
 * The office prices two kinds of item differently. Each main item carries its own listed
 * base premium. Components -- runes, moonstones -- are all priced at one uniform component
 * rate, so a new component type joins the list without a price of its own.
 */
public class PriceList {

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune");

    private static final int COMPONENT_BASE_PREMIUM = 25;

    public int basePremiumFor(Item item) {
        if (COMPONENT_TYPES.contains(item.type())) {
            return COMPONENT_BASE_PREMIUM;
        }
        return MAIN_ITEM_BASE_PREMIUMS.get(item.type());
    }
}
